// The REL module (inject/rel, built by inject/build.py into
// inject/build/wwrel.elf). The patcher converts RELELF, a relocatable
// ELF, into a REL (wwapi/rel FromELF), ships it in RELS.arc as module
// RELModuleID's file (d_a_rectangle.rel) and points the profile list's
// slot RELProcID (PROC_RECTANGLE) at the ELF's RELProfileSymbol. The
// game's dynamic linker loads it with the first actor of that proc.
const (
	RELModuleID      uint32 = 0x58
	RELProcID        uint16 = 0xB5
	RELProfileSymbol        = "g_profile_WWREL"
	// RELBuildID is the id the module's _prolog writes at
	// MailboxAddr+RELBuildIDOff (build.py: a CRC-32 of inject/rel's sources);
	// 0 when RELELF is empty.
	RELBuildID uint32 = 0xFB8986C3
	// The mailbox slack words (offsets from MailboxAddr, past the Mailbox
	// struct, include/wwrel.h WWREL_*): _prolog writes RELMagic at RELMagicOff
	// and RELBuildID at RELBuildIDOff, the actor's execute bumps the u32 at
	// RELFrameOff every frame, and _epilog clears the magic.
	RELMagic      uint32 = 0x5757524C
	RELMagicOff   uint32 = 0x1B0
	RELBuildIDOff uint32 = 0x1B4
	RELFrameOff   uint32 = 0x1B8
)

